    long long dist;
    int u;
} HeapNode;

int head[10005];
Edge edges[40005];
int edge_cnt = 0;

void add_edge(int u, int v, int w, int id) {
    edges[edge_cnt].to = v;
    edges[edge_cnt].weight = w;
    edges[edge_cnt].id = id;
    edges[edge_cnt].next = head[u];
    head[u] = edge_cnt++;
}

// DFS to find cycles
int visited[10005];
int parent_node[10005];
int parent_edge_weight[10005];
int depth[10005];

int cycle_cnt = 0;
long long cycle_len[10005];
int vertex_cycle[10005]; // -1 if not in a cycle, otherwise cycle_id

void dfs(int u, int p, int d) {
    visited[u] = 1;
    depth[u] = d;
    for (int e = head[u]; e != -1; e = edges[e].next) {
        int v = edges[e].to;
        int w = edges[e].weight;
        if (v == p) continue;

        if (visited[v] == 1) { // Back-edge found: cycle detected
            if (depth[v] < depth[u]) {
                cycle_cnt++;
                long long len = w;
                vertex_cycle[u] = cycle_cnt;
                int curr = u;
                while (curr != v) {
                    len += parent_edge_weight[curr];
                    curr = parent_node[curr];
                    vertex_cycle[curr] = cycle_cnt;
                }
                cycle_len[cycle_cnt] = len;
            }
        } else if (!visited[v]) {
            parent_node[v] = u;
            parent_edge_weight[v] = w;
            dfs(v, u, d + 1);
        }
    }
    visited[u] = 2;
}

// Min-Heap implementation for Dijkstra
HeapNode heap[40005];
int heap_size = 0;

void push(long long dist, int u) {
    int i = heap_size++;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (heap[p].dist <= dist) break;
        heap[i] = heap[p];
        i = p;
    }
    heap[i].dist = dist;
    heap[i].u = u;
}

HeapNode pop(void) {
    HeapNode ret = heap[0];
    HeapNode x = heap[--heap_size];
    int i = 0;
    while (i * 2 + 1 < heap_size) {
        int left = i * 2 + 1;
        int right = i * 2 + 2;
        int best = left;
        if (right < heap_size && heap[right].dist < heap[left].dist) {
            best = right;
        }
        if (heap[best].dist >= x.dist) break;
        heap[i] = heap[best];
        i = best;
    }
    heap[i] = x;
    return ret;
}

long long dist[10005];
long long min_dist_to_cycle[10005];

void dijkstra(int start, int n) {
    for (int i = 1; i <= n; i++) {
        dist[i] = INF;
    }
    heap_size = 0;

    dist[start] = 0;
    push(0, start);

    while (heap_size > 0) {
        HeapNode top = pop();
        long long d = top.dist;
        int u = top.u;

        if (d > dist[u]) continue;

        for (int e = head[u]; e != -1; e = edges[e].next) {
            int v = edges[e].to;
            int w = edges[e].weight;
            if (dist[u] + w < dist[v]) {
                dist[v] = dist[u] + w;
                push(dist[v], v);
            }
        }
    }
}

int main(void) {
    int E, R;
    if (scanf("%d %d", &E, &R) != 2) return 0;

    for (int i = 1; i <= E; i++) {
        head[i] = -1;
        vertex_cycle[i] = -1;
        visited[i] = 0;
    }

    for (int i = 0; i < R; i++) {
        int u, v, w;
        scanf("%d %d %d", &u, &v, &w);
        add_edge(u, v, w, i);
        add_edge(v, u, w, i);
    }

    for (int i = 1; i <= E; i++) {
        if (!visited[i]) {
            dfs(i, 0, 1);
        }
    }

    int K;
    if (scanf("%d", &K) != 1) return 0;

    while (K--) {
        int X;
        long long T;
        scanf("%d %lld", &X, &T);

        dijkstra(X, E);

        for (int c = 1; c <= cycle_cnt; c++) {
            min_dist_to_cycle[c] = INF;
        }

        for (int u = 1; u <= E; u++) {
            int cid = vertex_cycle[u];
            if (cid != -1 && dist[u] < min_dist_to_cycle[cid]) {
                min_dist_to_cycle[cid] = dist[u];
            }
        }

        long long ans = INF;
        for (int c = 1; c <= cycle_cnt; c++) {
            if (cycle_len[c] >= T && min_dist_to_cycle[c] < INF) {
                long long cost = 2 * min_dist_to_cycle[c] + cycle_len[c];
                if (cost < ans) {
                    ans = cost;
                }
            }
        }

        if (ans >= INF) {
            printf("-1\n");
        } else {
            printf("%lld\n", ans);
        }
    }

    return 0;
}
